const rtdal000774Source0001 = `test_that("reduce() stops early on reduced input", {
  reducer <- function(result, input) {
    if (input %% 2 == 0) {
      done(result)
    } else {
      c(result, input)
    }
  }

  expect_identical(reduce(1:5, reducer), 1L)
  expect_identical(reduce(int(1L, 3L, 5:10), reducer), int(1L, 3L, 5L))
})`

const rtdal000774Source0002 = "test_that(\"reduce_steps() calls initial step for initial value\", {\n  builder <- function(result, input) {\n    if (missing(result) && missing(input)) {\n      stop(\"called for init value\")\n    }\n  }\n\n  steps <- compose(iter_map(`+`, 1), iter_map(`+`, 1))\n  expect_error(reduce_steps(NULL, steps, builder), \"called for init value\")\n})"

const rtdal000774Source0003 = "test_that(\"reduce_steps() calls initial step for result completion\", {\n  builder <- function(result, input) {\n    if (missing(result) && missing(input)) {\n      return(NULL)\n    }\n    if (missing(input)) {\n      stop(\"called for init completion\")\n    }\n  }\n\n  steps <- compose(iter_map(`+`, 1), iter_map(`+`, 1))\n  expect_error(reduce_steps(NULL, steps, builder), \"called for init completion\")\n})"

const rtdal000774Source0004 = `test_that("into() creates vector of requested type", {
  # Also tested indirectly via take tests above
  expect_identical(into(new_double(3), 1:3), dbl(1:3))
})`

const rtdal000774Source0005 = `test_that("into() shrinks vector if needed", {
  expect_identical(into(integer(10), 1:3), 1:3)
})`

const rtdal000774Source0006 = `test_that("into() grows vector if needed", {
  expect_identical(into(integer(1), 1:3), 1:3)
})`

const rtdal000774Source0007 = `test_that("collect(n = ) fails if not enough elements", {
  expect_error(collect(1:10, n = 15), "10 / 15 elements")
})`

const rtdal000774Source0008 = `test_that("can reduce iterators", {
  iter <- as_iterator(1:3)
  out <- reduce_steps(iter, NULL, along_builder(chr()))
  expect_identical(out, as.character(1:3))
})`

const rtdal000774Source0009 = `test_that("reducing exhausted iterators produces empty output", {
  expect_identical(
    collect(function() exhausted()),
    list()
  )
})`

const rtdal000774Source0010 = "test_that(\"collect() retains `NULL` values\", {\n  g <- function() {\n    i <- 0\n    function() {\n      i <<- i + 1\n      if (i > 3) {\n        exhausted()\n      } else {\n        out[[i]]\n      }\n    }\n  }\n\n  out <- list(1, 2, NULL)\n  expect_equal(collect(g()), out)\n\n  out <- list(1, NULL, 2)\n  expect_equal(collect(g()), out)\n})"

const rtdal000774Source0011 = "test_that(\"collect() calls `as_iterator()`\", {\n  local_methods(\n    as_iterator.coro_foobar = function(x) {\n      called <- FALSE\n      function() {\n        out <- if (called) exhausted() else \"foo\"\n        called <<- TRUE\n        out\n      }\n    }\n  )\n  foobar <- structure(list(), class = \"coro_foobar\")\n  expect_equal(\n    collect(foobar),\n    list(\"foo\")\n  )\n})"

const rtdal000774Source0012 = `test_that("collect() preserves type (#32)", {
  expect_equal(
    collect(gen(for (i in 1:3) yield(i))),
    as.list(1:3)
  )
  expect_equal(
    wait_for(async_collect(async_generator(function() for (i in 1:3) yield(i))())),
    as.list(1:3)
  )

  expect_equal(
    collect(gen(for (i in 1:3) yield(list(i)))),
    lapply(1:3, list)
  )
  expect_equal(
    wait_for(async_collect(async_generator(function() for (i in 1:3) yield(list(i)))())),
    lapply(1:3, list)
  )

  expect_equal(
    collect(gen(for (i in 1:3) yield(mtcars[i, 1:3]))),
    lapply(1:3, function(i) mtcars[i, 1:3])
  )
  expect_equal(
    wait_for(async_collect(async_generator(function() for (i in 1:3) yield(mtcars[i, 1:3]))())),
    lapply(1:3, function(i) mtcars[i, 1:3])
  )
})`

