const rtdal000804Source0001 = `Encoding_ <- function(x) {
  if (is.factor(x) && length(levels(x)) < length(x)) {
    Encoding(levels(x))
  } else {
    if (!is.character(x)) x <- as.character(x)
    Encoding(x)
  }
}`

const rtdal000804Source0002 = `sub_ <- function(pattern, replacement, x, ...) {
  enc <- Encoding_(x)
  ret <- sub(pattern, replacement, x, ...)
  if (length(ret)) Encoding(ret) <- enc
  ret
}`

const rtdal000804Source0003 = `gsub_ <- function(pattern, replacement, x, ...) {
  enc <- Encoding_(x)
  ret <- gsub(pattern, replacement, x, ...)
  if (length(ret)) Encoding(ret) <- enc
  ret
}`

const rtdal000804Source0004 = `strsplit_ <- function(x, ...) {
  enc <- Encoding_(x)
  ret <- strsplit(x, ...)
  for (i in seq_along(ret)) {
    Encoding(ret[[i]]) <- enc[i]
  }
  ret
}`

