const rtdal000813Source0001 = `map_to_ansi <- function(x, text = NULL) {

  if (is.null(text)) {
    text <- non_matching(re_table(ansi_regex, x), x, empty=TRUE)
  }

  map <- lapply(
    text,
    function(text) {
      cbind(
        pos = cumsum(c(1, text[, "length"], Inf)),
        offset = c(text[, "start"] - 1, tail(text[, "end"], 1), NA)
      )
    })

  function(pos) {
    pos <- rep(pos, length.out = length(map))
    mapply(pos, map, FUN = function(pos, table) {
      if (pos < 1) {
        pos
      } else {
        slot <- which(pos < table[, "pos"])[1] - 1
        table[slot, "offset"] + pos - table[slot, "pos"] + 1
      }
    })
  }
}`

const rtdal000813Source0002 = `col_nchar <- function(x, ...) {
  base::nchar(strip_style(x), ...)
}`

const rtdal000813Source0003 = `col_substr <- function(x, start, stop) {
  if(!is.character(x)) x <- as.character(x)
  if(!length(x)) return(x)
  start <- as.integer(start)
  stop <- as.integer(stop)
  if(!length(start) || !length(stop))
    stop("invalid substring arguments")
  if(anyNA(start) || anyNA(stop))
    stop("non-numeric substring arguments not supported")
  ansi <- re_table(ansi_regex, x)
  text <- non_matching(ansi, x, empty=TRUE)
  mapper <- map_to_ansi(x, text = text)
  nstart <- mapper(start)
  nstop  <- mapper(stop)

  bef <- base::substr(x, 1, nstart - 1)
  aft <- base::substr(x, nstop + 1, base::nchar(x))
  ansi_bef <- vapply(regmatches(bef, gregexpr(ansi_regex, bef)),
                     paste, collapse = "", FUN.VALUE = "")
  ansi_aft <- vapply(regmatches(aft, gregexpr(ansi_regex, aft)),
                     paste, collapse = "", FUN.VALUE = "")

  paste(sep = "", ansi_bef, base::substr(x, nstart, nstop), ansi_aft)
}`

const rtdal000813Source0004 = `col_substring <- function(text, first, last = 1000000L) {
  if (!is.character(text)) text <- as.character(text)
  n <- max(lt <- length(text), length(first), length(last))
  if (lt && lt < n) text <- rep_len(text, length.out = n)
  col_substr(text, as.integer(first), as.integer(last))
}`

const rtdal000813Source0005 = "col_strsplit <- function(x, split, ...) {\n  split <- try(as.character(split), silent=TRUE)\n  if(inherits(split, \"try-error\") || !is.character(split) || length(split) > 1L)\n    stop(\"`split` must be character of length <= 1, or must coerce to that\")\n  if(!length(split)) split <- \"\"\n  plain <- strip_style(x)\n  splits <- re_table(split, plain, ...)\n  chunks <- non_matching(splits, plain, empty = TRUE)\n  # silently recycle `split`; doesn't matter currently since we don't support\n  # split longer than 1, but might in future\n  split.r <- rep(split, length.out=length(x))\n  # Drop empty chunks to align with `substr` behavior\n  chunks <- lapply(\n    seq_along(chunks),\n    function(i) {\n      y <- chunks[[i]]\n      # empty split means drop empty first match\n      if(nrow(y) && !nzchar(split.r[[i]]) && !head(y, 1L)[, \"length\"]) {\n        y <- y[-1L, , drop=FALSE]\n      }\n      # drop empty last matches\n      if(nrow(y) && !tail(y, 1L)[, \"length\"]) y[-nrow(y), , drop=FALSE] else y\n    }\n  )\n  zero.chunks <- !vapply(chunks, nrow, integer(1L))\n  # Pull out zero chunks from colored string b/c col_substring won't work\n  # with them\n  res <- vector(\"list\", length(chunks))\n  res[zero.chunks] <- list(character(0L))\n  res[!zero.chunks] <- mapply(\n    chunks[!zero.chunks], x[!zero.chunks], SIMPLIFY = FALSE,\n    FUN = function(tab, xx) col_substring(xx, tab[, \"start\"], tab[, \"end\"])\n  )\n  res\n}"

const rtdal000813Source0006 = `col_align <- function(text, width = getOption("width"),
                      align = c("left", "center", "right"),
                      type = "width") {

  align <- match.arg(align)
  nc <- col_nchar(text, type = type)

  if (!length(text)) return(text)

  if (align == "left") {
    paste0(text, make_space(width - nc))

  } else if (align == "center") {
    paste0(make_space(ceiling((width - nc) / 2)),
           text,
           make_space(floor((width - nc) / 2)))

  } else {
    paste0(make_space(width - nc), text)
  }
}`

const rtdal000813Source0007 = `make_space <- function(num, filling = " ") {
  num <- pmax(0, num)
  res <- strrep(filling, num)
  Encoding(res) <- Encoding(filling)
  res
}`

const rtdal000813Source0008 = `strrep <- function (x, times) {
  x = as.character(x)
  if (length(x) == 0L) return(x)

  mapply(
    function(x, times) {
      if (is.na(x) || is.na(times)) {
        NA_character_
      } else if (times <= 0L) {
        ""
      } else {
        paste0(rep(x, times), collapse = "")
      }
    },
    x, times,
    USE.NAMES = FALSE
  )
}`

