const rtdal000848Source0001 = `new_handle <- function(...){
  h <- .Call(R_new_handle)
  handle_setopt(h, ...)
  h
}`

const rtdal000848Source0002 = `handle_setopt <- function(handle, ..., .list = list()){
  stopifnot(inherits(handle, "curl_handle"))
  values <- c(list(...), .list)
  opt_names <- fix_options(tolower(names(values)))
  keys <- as.integer(curl_options()[opt_names])
  na_keys <- is.na(keys)
  if(any(na_keys)){
    bad_opts <- opt_names[na_keys]
    stop("Unknown option", ifelse(length(bad_opts) > 1, "s: ", ": "),
      paste(bad_opts, collapse=", "))
  }
  stopifnot(length(keys) == length(values))
  .Call(R_handle_setopt, handle, keys, values)
  invisible(handle)
}`

const rtdal000848Source0003 = `handle_setheaders <- function(handle, ..., .list = list()){
  x <- c(list(...), .list)
  if(!all(vapply(x, is.character, logical(1)))){
    stop("All headers must be strings.")
  }
  handle_setopt(handle, httpheader = format_request_headers(x))
}`

const rtdal000848Source0007 = `handle_setform <- function(handle, ..., .list = list()){
  stopifnot(inherits(handle, "curl_handle"))
  form <- c(list(...), .list)
  for(i in seq_along(form)){
    val <- form[[i]];
    if(is.character(val)){
      form[[i]] <- charToRaw(enc2utf8(val))
    } else if(!is.raw(val) && !inherits(val, "form_file") && !inherits(val, "form_data")){
      stop("Unsupported value type for form field '", names(form[i]), "'.")
    }
  }
  .Call(R_handle_setform, handle, form)
  invisible(handle)
}`

const rtdal000848Source0009 = "handle_cookies <- function(handle){\n  stopifnot(inherits(handle, \"curl_handle\"))\n  cookies <- .Call(R_get_handle_cookies, handle)\n  df <- if(length(cookies)){\n    values <- lapply(strsplit(cookies, split=\"\\t\"), `[`, 1:7)\n    as.data.frame(do.call(rbind, values), stringsAsFactors = FALSE)\n  } else {\n    as.data.frame(matrix(ncol=7, nrow=0))\n  }\n  names(df) <- c(\"domain\", \"flag\", \"path\", \"secure\", \"expiration\", \"name\", \"value\")\n  df$flag <- as.logical(df$flag)\n  df$secure <- as.logical(df$secure)\n  expires <- as.numeric(df$expiration)\n  expires[expires==0] <- Inf\n  class(expires) = c(\"POSIXct\", \"POSIXt\");\n  df$expiration <- expires\n  df\n\n}"

const rtdal000848Source0014 = `print.curl_handle <- function(x, ...){
  stopifnot(inherits(x, "curl_handle"))
  url <- handle_data(x)$url
  if(!nchar(url)) url <- "empty"
  cat(sprintf("<curl handle> (%s)\n", url))
}`

const rtdal000848Source0016 = `fix_options <- function(opt_names){
  # Recent libcurl should use xferinfo instead of progress
  has_xferinfo <- length(curl_options("xferinfofunction"))
  if(has_xferinfo){
    opt_names[opt_names == "progressfunction"] <- "xferinfofunction"
    return(opt_names)
  } else {
    opt_names[opt_names == "xferinfofunction"] <- "progressfunction"
    return(opt_names)
  }
}`

