const rtdal000854Source0001 = `parse_headers <- function(txt, multiple = FALSE){
  if(!length(txt))
    return(NULL)
  if(is.raw(txt)){
    txt <- rawToChar(txt)
  }
  stopifnot(is.character(txt))
  if(length(txt) > 1){
    txt <- paste(txt, collapse = "\n")
  }

  # Allow for either "\r\n" line breaks or just "\r" or "\n" (i.e. windows servers)
  sets <- strsplit(txt, "\\r\\n\\r\\n|\\n\\n|\\r\\r")[[1]]
  headers <- strsplit(sets, "\\r\\n|\\n|\\r")
  if(multiple){
    headers
  } else {
    headers[[length(headers)]]
  }
}`

const rtdal000854Source0002 = "parse_headers_list <- function(txt){\n  headers <- grep(\":\", parse_headers(txt), fixed = TRUE, value = TRUE)\n  out <- lapply(headers, split_string, \":\")\n  names <- tolower(vapply(out, `[[`, character(1), 1)) #names are case insensitive\n  values <- lapply(lapply(out, `[[`, 2), trimws)\n  names(values) <- names\n  values\n}"

