const rtdal000855Source0001 = `curl_parse_url <- function(url, baseurl = NULL, decode = TRUE, params = TRUE,
                           default_scheme = FALSE){
  stopifnot(is.character(url))
  stopifnot(length(url) == 1)
  baseurl <- as.character(baseurl)

  # Workaround for #366
  if(length(baseurl) && substr(url, 1, 1) == '#'){
    url <- sub('(#.*)?$', url, baseurl)
  }

  result <- .Call(R_parse_url, url, baseurl, default_scheme)
  result$url <- toupper_url_encoding(result$url)


  # Need to parse query before url-decoding
  if(params){
    tryCatch({
      result$params <- parse_query_urlencoded(result$query)
      result$query <- NULL
    }, error = message)
  }

  result$path <- normalize_field(result$path, decode)
  result$query <- normalize_field(result$query, decode)
  result$fragment <- normalize_field(result$fragment, decode)
  result$user <- normalize_field(result$user, decode)
  result$password <- normalize_field(result$password, decode)
  result
}`

const rtdal000855Source0004 = `normalize_field <- function(x, decode = TRUE){
  if(is.null(x)){
    return(x)
  }
  if(isTRUE(decode)){
    curl_unescape(x)
  } else {
    toupper_url_encoding(x)
  }
}`

const rtdal000855Source0005 = "parse_query_urlencoded <- function(query){\n  if(!length(query)) return(character())\n  query <- chartr('+',' ', query)\n  argstr <- strsplit(query, \"&\", fixed = TRUE)[[1]]\n  args <- lapply(argstr, function(x){\n    c(curl_unescape(strsplit(x, \"=\", fixed = TRUE)[[1]]), \"\")\n  })\n  values <- vapply(args, `[`, character(1), 2)\n  names(values) <- vapply(args, `[`, character(1), 1)\n  return(values)\n}"

