const rtdal000906Source0083 = `gweighted.mean = function(x, w, ..., na.rm=FALSE) {
  if (missing(w)) gmean(x, na.rm)
  else {
    if (na.rm) { # take those indices out of the equation by setting them to 0
      ix = is.na(x)
      x[ix] = 0.0
      w[ix] = 0.0
    }
    gsum((w!=0.0)*x*w, na.rm=FALSE)/gsum(w, na.rm=FALSE)
  }
}`

const rtdal000906Source0096 = "`.g[_ok` = function(q, x) {\n  length(q) == 3L &&\n    is_constantish(q[[3L]], check_singleton = TRUE) &&\n    (q[[1L]] != \"[[\" || eval(call('is.atomic', q[[2L]]), envir=x)) &&\n    !(as.character(q[[3L]]) %chin% names(x)) && is.numeric(q3 <- eval(q[[3L]], parent.frame(3L))) && length(q3)==1L && q3>0L\n}"

const rtdal000906Source0098 = `.get_gcall = function(q) {
  if (!is.call(q)) return(NULL)
  # is.symbol() is for #1369, #1974 and #2949
  if (!is.symbol(q[[2L]])) return(NULL)
  q1 = q[[1L]]
  if (is.symbol(q1)) return(if (q1 %chin% gfuns) q1)
  if (!q1 %iscall% "::") return(NULL)
  if (q1[[2L]] != "data.table") return(NULL)
  if (q1[[3L]] %chin% gdtfuns) return(q1[[3L]])
  NULL
}`

const rtdal000906Source0099 = `.arg_is_narm = function(expr, which=3L) !is.null(nm <- names(expr)[which]) && startsWith(nm, "na")`

const rtdal000906Source0100 = ".gforce_ok = function(q, x) {\n  if (is.N(q)) return(TRUE) # For #334\n  q1 = .get_gcall(q)\n  if (is.null(q1)) return(FALSE)\n  if (!(q2 <- q[[2L]]) %chin% names(x) && q2 != \".I\") return(FALSE)  # 875\n  if (length(q)==2L || (.arg_is_narm(q) && is_constantish(q[[3L]]))) return(TRUE)\n  switch(as.character(q1),\n    \"shift\" = .gshift_ok(q),\n    \"weighted.mean\" = .gweighted.mean_ok(q, x),\n    \"tail\" = , \"head\" = .ghead_ok(q),\n    \"[[\" = , \"[\" = `.g[_ok`(q, x),\n    FALSE\n  )\n}"

const rtdal000906Source0101 = `.gforce_jsub = function(q, names_x) {
  call_name = if (is.symbol(q[[1L]])) q[[1L]] else q[[1L]][[3L]] # latter is like data.table::shift, #5942. .gshift_ok checked this will work.
  q[[1L]] = as.name(paste0("g", call_name))
  # gforce needs to evaluate arguments before calling C part TODO: move the evaluation into gforce_ok
  # do not evaluate vars present as columns in x
  if (length(q) >= 3L) {
    for (i in 3:length(q)) {
      if (is.symbol(q[[i]]) && !(q[[i]] %chin% names_x)) q[[i]] = eval(q[[i]], parent.frame(2L)) # tests 1187.2 & 1187.4
    }
  }
  q
}`

const rtdal000906Source0102 = ".check_nested_walrus = function(e, check_entries, call_name) {\n  for (jj in check_entries) if (e[[jj]] %iscall% \":=\")\n    stopf(\"It looks like you re-used `:=` in argument %d a functional assignment call -- use `=` instead: %s(col1=val1, col2=val2, ...)\", jj-1L, call_name)\n}"

const rtdal000906Source0103 = `.prepareFastSubset = function(isub, x, enclos, notjoin, verbose=FALSE) {
  ## helper that decides, whether a fast binary search can be performed, if i is a call
  ## For details on the supported queries, see \code{\link{datatable-optimize}}
  ## Additional restrictions are imposed if x is .SD, or if options indicate that no optimization
  ## is to be performed
  #' @param isub the substituted i
  #' @param x the data.table
  #' @param enclos The environment where to evaluate when RHS is not a column of x
  #' @param notjoin boolean that is set before, indicating whether i started with '!'.
  #' @param verbose TRUE for detailed output
  #' @return If i is not fast subsettable, NULL. Else, a list with entries:
  #'        out$i: a data.table that will be used as i with proper column names and key.
  #'        out$on: the correct 'on' statement that will be used for x[i, on =...]
  #'        out$notjoin Bool. In some cases, notjoin is updated within the function.
  #'        ATTENTION: If nothing else helps, an auto-index is created on x unless options prevent this.
  if(getOption("datatable.optimize") < 3L) return(NULL) ## at least level three optimization required.
  if (!is.call(isub)) return(NULL)
  if (.Call(C_islocked, x)) return(NULL)  # fix for #958, don't create auto index on '.SD'.
  ## a list of all possible operators with their translations into the 'on' clause
  validOps = list(op = c("==", "%in%", "%chin%"),
                   on = c("==", "==",   "=="))

  ## Determine, whether the nature of isub in general supports fast binary search
  remainingIsub = isub
  i = list()
  on = character(0L)
  nonEqui = FALSE
  while(length(remainingIsub)){
    if(is.call(remainingIsub)){
      if (length(remainingIsub[[1L]]) != 1L) return(NULL) ## only single symbol, either '&' or one of validOps allowed.
      if (remainingIsub[[1L]] != "&"){ ## only a single expression present or a different connection.
        stub = remainingIsub
        remainingIsub = NULL ## there is no remainder to be evaluated after stub.
      } else {
        ## multiple expressions with & connection.
        if (notjoin) return(NULL) ## expressions of type DT[!(a==1 & b==2)] currently not supported
        stub = remainingIsub[[3L]] ## the single column expression like col == 4
        remainingIsub = remainingIsub[[2L]] ## the potentially longer expression with potential additional '&'
      }
    } else { ## single symbol present
      stub = remainingIsub
      remainingIsub = NULL
    }
    ## check the stub if it is fastSubsettable
    if(is.symbol(stub)){
      ## something like DT[x & y]. If x and y are logical columns, we can optimize.
      col = as.character(stub)
      if(!col %chin% names(x)) return(NULL)
      if(!is.logical(x[[col]])) return(NULL)
      ## redirect to normal DT[x == TRUE]
      stub = call("==", as.symbol(col), TRUE)
    }
    if (length(stub[[1L]]) != 1L) return(NULL) # nocov Whatever it is, definitely not one of the valid operators
    operator = as.character(stub[[1L]])
    if (!operator %chin% validOps$op) return(NULL) ## operator not supported
    if (!is.name(stub[[2L]])) return(NULL)
    col = as.character(stub[[2L]])
    if (!col %chin% names(x)) return(NULL) ## any non-column name prevents fast subsetting
    if(col %chin% names(i)) return(NULL) ## repeated appearance of the same column not supported (e.g. DT[x < 3 & x < 5])
    ## now check the RHS of stub
    RHS = eval(stub[[3L]], x, enclos)
    if (is.list(RHS)) RHS = as.character(RHS)  # fix for #961
    if (length(RHS) != 1L && !operator %chin% c("%in%", "%chin%")){
      if (length(RHS) != nrow(x)) stopf("RHS of %s is length %d which is not 1 or nrow (%d). For robustness, no recycling is allowed (other than of length 1 RHS). Consider %%in%% instead.", operator, length(RHS), nrow(x))
      return(NULL) # DT[colA == colB] regular element-wise vector scan
    }
    if ( (mode(x[[col]]) != mode(RHS)) ||                # mode() so that doubleLHS/integerRHS and integerLHS/doubleRHS&fitsInInt32 are optimized (both sides mode 'numeric')
         (is.factor(x[[col]])+is.factor(RHS) == 1L) ||   # but factor is also mode 'numeric' so treat that separately
         (is.integer(x[[col]]) && is.double(RHS) && !fitsInInt32(RHS)) ) { # and if RHS contains fractions then don't optimize that as bmerge truncates the fractions to match to the target integer type
      # re-direct non-matching type cases to base R, as data.table's binary
      # search based join is strict in types. #957, #961 and #1361
      # the mode() checks also deals with NULL since mode(NULL)=="NULL" and causes this return, as one CRAN package (eplusr 0.9.1) relies on
      return(NULL)
    }
    if (!operator %chin% c("%in%", "%chin%")) {
      # additional requirements for notjoin and NA values. Behaviour is different for %in%, %chin% compared to other operators
      # RHS is of length=1 or n
      if (any_na(as_list(RHS))) {
        ## dt[x == NA] or dt[x <= NA] will always return empty
        notjoin = FALSE
        RHS = RHS[0L]
      } else if (notjoin) {
        ## dt[!x == 3] must not return rows where x is NA
        RHS = c(RHS, if (is.double(RHS) && is.double(x[[col]])) c(NA, NaN) else NA)
      }
    }
    ## if it passed until here, fast subset can be done for this stub
    i = c(i, setNames(list(RHS), col))
    on = c(on, setNames(paste0(col, validOps$on[validOps$op == operator], col), col))
    ## loop continues with remainingIsub
  }
  if (length(i) == 0L) internal_error("i became length-0") # nocov
  ## convert i to data.table with all combinations in rows.
  if(length(i) > 1L && prod(lengths(i)) > 1e4L){
    ## CJ would result in more than 1e4 rows. This would be inefficient, especially memory-wise #2635
    if (verbose) {catf("Subsetting optimization disabled because the cross-product of RHS values exceeds 1e4, causing memory problems.\n");flush.console()}
    return(NULL)
  }
  ## Care is needed with names as we construct i
  ## with 'CJ' and 'do.call' and this would cause problems if colNames were 'sorted' or 'unique'
  ## as these two would be interpreted as args for CJ
  colNames = names(i)
  names(i) = NULL
  i$sorted = FALSE
  i$unique = TRUE
  i = do.call(CJ, i)
  setnames(i, colNames)
  idx = NULL
  if (is.null(idx)) {
    ## check whether key fits the columns in i.
    ## order of key columns makes no difference, as long as they are all upfront in the key, I believe.
    key_head = head(key(x), length(i))
    if (all(names(i) %chin% key_head)) {
      if (verbose) {catf("Optimized subsetting with key %s", brackify(key_head)); flush.console()}
      idx = integer(0L) ## integer(0L) not NULL! Indicates that x is ordered correctly.
      idxCols = key_head ## in correct order!
    }
  }
  if (is.null(idx)){
    if (!getOption("datatable.use.index")) return(NULL) # #1422
    ## check whether an existing index can be used
    ## An index can be used if it corresponds exactly to the columns in i (similar to the key above)
    candidates = indices(x, vectors = TRUE)
    idx = NULL
    for (cand in candidates){
      if (all(names(i) %chin% cand) && length(cand) == length(i)){
        idx = attr(attr(x, "index", exact=TRUE), paste0("__", cand, collapse = ""), exact = TRUE)
        idxCols = cand
        break
      }
    }
    if (!is.null(idx)){
      if (verbose) {catf("Optimized subsetting with index '%s'\n", paste(idxCols, collapse = "__"));flush.console()}
    }
  }
  if (is.null(idx)){
    ## if nothing else helped, auto create a new index that can be used
    if (!getOption("datatable.auto.index")) return(NULL)
    idxCols = names(i)
    if (verbose) {catf("Creating new index '%s'\n", paste(idxCols, collapse = "__"));flush.console()}
    if (verbose) {last.started.at=proc.time();catf("Creating index %s done in ...", paste(idxCols, collapse = "__"));flush.console()}
    idx = forderv(x, idxCols, sort=TRUE, retGrp=FALSE, reuseSorting=TRUE)
    maybe_reset_index(x, idx, idxCols) ## forder can write index, but disabled for now, see #4386
    if (verbose) {cat(timetaken(last.started.at),"\n");flush.console()}
    if (verbose) {catf("Optimized subsetting with index '%s'\n", paste(idxCols, collapse = "__"));flush.console()}
  }
  if(!is.null(idxCols)){
    setkeyv(i, idxCols)
    on = on[idxCols] ## make sure 'on' is in the correct order. Otherwise the logic won't recognise that a key / index already exists.
  }
  list(i=i, on=on, notjoin=notjoin)
}`

const rtdal000906Source0104 = ".parse_on = function(onsub, isnull_inames) {\n  ## helper that takes the 'on' string(s) and extracts comparison operators and column names from it.\n  #' @param onsub the substituted on\n  #' @param isnull_inames bool; TRUE if i has no names.\n  #' @return List with two entries:\n  #'         'on' : character vector providing the column names for the join.\n  #'                Names correspond to columns in x, entries correspond to columns in i\n  #'         'ops': integer vector. Gives the indices of the operators that connect the columns in x and i.\n  ops = c(\"==\", \"<=\", \"<\", \">=\", \">\", \"!=\")\n  pat = paste0(\"(\", ops, \")\", collapse=\"|\")\n  if (onsub %iscall% 'eval') {\n    onsub = eval(onsub[[2L]], parent.frame(2L), parent.frame(2L))\n  }\n  if (onsub %iscall% c('list', '.')) {\n    spat = paste0(\"[ ]+(\", pat, \")[ ]+\")\n    onsub = lapply(as.list(onsub)[-1L], function(x) gsub(spat, \"\\\\1\", deparse(x, width.cutoff=500L)))\n    onsub = as.call(c(quote(c), onsub))\n  }\n  on = eval(onsub, parent.frame(2L), parent.frame(2L))\n  if (length(on) == 0L || !is.character(on))\n    stopf(\"'on' argument should be a named atomic vector of column names indicating which columns in 'i' should be joined with which columns in 'x'.\")\n  ## extract the operators and potential variable names from 'on'.\n  ## split at backticks to take care about variable names like `col1<=`.\n  pieces = strsplit(on, \"(?=[`])\", perl = TRUE)\n  xCols  = character(length(on))\n  ## if 'on' is named, the names are the xCols for sure\n  if(!is.null(names(on))){\n    xCols = names(on)\n  }\n  iCols     = character(length(on))\n  operators = character(length(on))\n  ## loop over the elements and extract operators and column names.\n  for(i in seq_along(pieces)){\n    thisCols      = character(0L)\n    thisOperators = character(0L)\n    j = 1L\n    while(j <= length(pieces[[i]])){\n      if(pieces[[i]][j] == \"`\"){\n        ## start of a variable name with backtick.\n        thisCols = c(thisCols, pieces[[i]][j+1L])\n        j = j+3L # +1 is the column name, +2 is delimiting \"`\", +3 is next relevant entry.`\n      } else {\n        ## no backtick\n        ## search for operators\n        thisOperators = c(thisOperators,\n                           unlist(regmatches(pieces[[i]][j], gregexpr(pat, pieces[[i]][j])),\n                                  use.names = FALSE))\n        ## search for column names\n        thisCols = c(thisCols, trimws(strsplit(pieces[[i]][j], pat)[[1L]]))\n        ## there can be empty string column names because of trimws, remove them\n        thisCols = thisCols[nzchar(thisCols)]\n        j = j+1L\n      }\n    }\n    if (length(thisOperators) == 0L) {\n      ## if no operator is given, it must be ==\n      operators[i] = \"==\"\n    } else if (length(thisOperators) == 1L) {\n      operators[i] = thisOperators\n    } else {\n      ## multiple operators found in one 'on' part. Something is wrong.\n      stopf(\"Found more than one operator in one 'on' statement: %s. Please specify a single operator.\", on[i])\n    }\n    if (length(thisCols) == 2L){\n      ## two column names found, first is xCol, second is iCol for sure\n      xCols[i] = thisCols[1L]\n      iCols[i] = thisCols[2L]\n    } else if (length(thisCols) == 1L){\n      ## a single column name found. Can mean different things\n      if(xCols[i] != \"\"){\n        ## xCol is given by names(on). thisCols must be iCol\n        iCols[i] = thisCols[1L]\n      } else if (isnull_inames){\n        ## i has no names. It will be given the names V1, V2, ... automatically.\n        ## The single column name is the x column. It will match to the ith column in i.\n        xCols[i] = thisCols[1L]\n        iCols[i] = paste0(\"V\", i)\n      } else {\n        ## i has names and one single column name is given by on.\n        ## This means that xCol and iCol have the same name.\n        xCols[i] = thisCols[1L]\n        iCols[i] = thisCols[1L]\n      }\n    } else if (length(thisCols) == 0L){\n      stopf(\"'on' contains no column name: %s. Each 'on' clause must contain one or two column names.\", on[i])\n    } else {\n      stopf(\"'on' contains more than 2 column names: %s. Each 'on' clause must contain one or two column names.\", on[i])\n    }\n  }\n  idx_op = match(operators, ops, nomatch=0L)\n  if (any(idx_op %in% c(0L, 6L)))\n    stopf(\"Invalid join operators %s. Only allowed operators are %s.\", brackify(operators[idx_op %in% c(0L, 6L)]), brackify(ops[1:5]))\n  ## the final on will contain the xCol as name, the iCol as value\n  on = iCols\n  names(on) = xCols\n  list(on = on, ops = idx_op)\n}"

